<template><div class="workflow"><PageHero title="我的办理进度" subtitle="房源、内容与平台通知，都在这里接着办。"/><main><nav><button v-for="(label,key) in tabs" :key="key" :class="{on:tab===key}" @click="tab=key">{{label}}</button><RouterLink to="/app/publish-house">发布房源 ↗</RouterLink></nav><p v-if="error" role="alert">{{error}}</p><p v-if="loading">正在加载……</p><p v-else-if="!rows.length">这里暂时没有记录。</p>
<article v-for="r in rows" :key="r.id"><div><h3>{{r.title||r.houseTitle||'房源举报'}}</h3><span>{{label(r.status)}}</span><p>{{r.content}}</p><p v-if="r.reviewNote">处理意见：{{r.reviewNote}}</p><p v-if="r.response">处理答复：{{r.response}}</p><small>{{r.created_at||r.updatedAt}}</small></div><div class="actions"><template v-if="tab==='houses'"><button @click="open(r)">查看材料与记录</button><RouterLink :to="'/app/publish-house?edit='+r.id">编辑房源</RouterLink><button :disabled="busy||r.status==='OFFLINE'" @click="withdraw(r)">下架房源</button></template><template v-if="tab==='notices'"><button v-if="!r.read_at" @click="read(r)">标为已读</button><span v-else>已读</span></template><template v-if="['reviews','guides'].includes(tab)&&['REJECTED','OFFLINE'].includes(r.status)"><button @click="resubmit(r)">修改并重新提交</button></template></div></article>
<section v-if="selected" class="application"><button @click="selected=null">关闭材料详情 ×</button><h2>{{selected.house.title}}</h2><p>房源状态：{{label(selected.house.status)}}</p><ul><li v-for="(h,i) in selected.history" :key="i">{{h.createdAt}} · {{h.note}}</li></ul><TrustApplication :key="selected.house.id" :house-id="selected.house.id" :initial="selected.application" @submitted="submitted"/></section>
<section v-if="editing" class="application"><h2>修改后重新审核</h2><input v-if="tab==='guides'" v-model="editTitle" aria-label="标题"/><textarea v-model="editContent" rows="8" aria-label="正文"/><button :disabled="busy" @click="saveContent">提交审核</button><button @click="editing=null">取消</button></section>
</main></div></template>
<script setup>
import {ref,watch,onMounted} from 'vue'
import request from '../api/index'
import PageHero from '../components/PageHero.vue'
import TrustApplication from '../components/TrustApplication.vue'
const tabs={notices:'平台通知',houses:'我的房源',reports:'我的举报',reviews:'我的评价',guides:'我的攻略'},tab=ref('notices'),rows=ref([]),loading=ref(false),busy=ref(false),error=ref(''),selected=ref(null),editing=ref(null),editTitle=ref(''),editContent=ref('')
const label=s=>({APPROVED:'已通过',PENDING:'待审核',REJECTED:'未通过',OFFLINE:'已下架',published:'已发布',RESOLVED:'已处理',DISMISSED:'未采纳'}[s]||s||'')
let version=0
async function load(){const v=++version;loading.value=true;error.value='';selected.value=null;editing.value=null;try{const path={notices:'/trust/notices',houses:'/trust/mine',reports:'/trust/reports',reviews:'/trust/content/reviews',guides:'/trust/content/guides'}[tab.value];const r=await request.get(path);if(v===version)rows.value=r.data||[]}catch(e){if(v===version)error.value=e.message}finally{if(v===version)loading.value=false}}
async function action(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.response?.data?.message||e.message}finally{busy.value=false}}
async function read(r){await action(async()=>{await request.post('/trust/notices/'+r.id+'/read');r.read_at=new Date().toISOString()})}
async function open(r){await action(async()=>{selected.value=(await request.get('/trust/application/'+r.id)).data})}
async function withdraw(r){if(!confirm('确认下架这套房源？聊天记录将保留，重新上架需要审核。'))return;await action(async()=>{await request.post('/trust/withdraw/'+r.id);await load()})}
async function submitted(){await load();error.value='资料已提交，审核结果将在平台通知中反馈。'}
async function resubmit(r){editing.value=r;editTitle.value=r.title;editContent.value=(await request.get('/trust/content/'+tab.value+'/'+r.id)).data.content}
async function saveContent(){await action(async()=>{await request.put('/trust/content/'+tab.value+'/'+editing.value.id,{title:editTitle.value,content:editContent.value});await load()})}
watch(tab,load);onMounted(load)
</script>
<style scoped>.workflow{background:var(--jade-paper);min-height:80vh}.workflow main{max-width:1200px;margin:auto;padding:25px var(--page-gutter) 80px}.workflow nav,.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:22px}.workflow button,.workflow a{border:1px solid var(--jade-line);padding:10px 16px;border-radius:4px;background:white;color:var(--jade-700);font-size:13px}.workflow button.on{background:var(--jade-900);color:white}.workflow article{padding:24px;border:1px solid var(--jade-line);margin:14px 0;background:#fffefa;display:flex;justify-content:space-between;gap:20px}.workflow h3{margin-bottom:12px}.workflow p,.workflow li{line-height:1.9;font-size:14px;white-space:pre-wrap}.workflow small{color:var(--jade-muted)}.workflow span{color:var(--jade-600);font-size:13px}.application{margin:24px 0;padding:22px;border:1px solid var(--jade-line);background:white}.application>button{margin-bottom:18px}.application ul{padding:20px}.application textarea,.application>input{display:block;width:100%;padding:14px;margin:16px 0;border:1px solid var(--jade-line)}@media(max-width:700px){.workflow article{flex-direction:column}}</style>
